                 'Northern Rockies', 'Great Basin', 'Western Great Basin*', 'Southwest', 
                 'Rocky Mountains', 'Eastern Area', 'Southern Area', 'Western Great Basin']

    result = []
    for col in area_cols:
        if col in clean_data.columns:
            df_area = clean_data.groupby('Year')[col].sum().reset_index()
