def process(calculate_zscore_final):
    abs_zscore = calculate_zscore_final.copy()
    abs_zscore['abs_zscore'] = abs_zscore['zscore'].abs()
    most_anomalous = abs_zscore.loc[abs_zscore['abs_zscore'].idxmax()]
    result = pd.DataFrame({
        'geographic_area': [most_anomalous['geographic_area']],
        'Year': [int(most_anomalous['Year'])],
        'zscore': [most_anomalous['zscore']]
    })
    return result

