def process(combine_sources) -> pd.DataFrame:
    stats = combine_sources.groupby('Geographic_Area').agg({
        'Acres': ['mean', 'std']
    }).reset_index()
    stats.columns = ['Geographic_Area', 'Mean_Acres', 'Std_Acres']
    return stats

