def process(clean_data) -> pd.DataFrame:
    areas = ['Alaska', 'Northwest', 'Northern California', 'Southern California', 
             'Northern Rockies', 'Great Basin', 'Southwest', 'Rocky Mountains', 
             'Eastern Area', 'Southern Area']

    records = []
    for year in clean_data['Year'].unique():
        lightning_row = clean_data[(clean_data['Year'] == year) & (clean_data['source'] == 'lightning')].iloc[0]
        human_row = clean_data[(clean_data['Year'] == year) & (clean_data['source'] == 'human')].iloc[0]

        for area in areas:
            light_acres = lightning_row[area] if pd.notna(lightning_row[area]) else 0
            human_acres = human_row[area] if pd.notna(human_row[area]) else 0
            total_acres = light_acres + human_acres

            records.append({
                'Year': year,
                'Area': area,
                'Acres': total_acres
            })

    return pd.DataFrame(records)

